<script setup lang="ts">
import {ref,watch} from 'vue';import ELK, {type ElkNode} from 'elkjs/lib/elk.bundled.js';import {save} from '@tauri-apps/plugin-dialog';import {api} from '../api';import {useLab} from '../store';
export interface GraphNode{id:string,label:string,detail?:string}export interface GraphEdge{source:string,target:string,label?:string}
const props=defineProps<{nodes:GraphNode[],edges:GraphEdge[],selected?:string,completed?:string[],progress?:number,reduced?:boolean,activeEdges?:string[],dangerEdges?:string[],visibleEdges?:string[]}>();const emit=defineEmits<{select:[id:string]}>();const lab=useLab();const svg=ref<SVGSVGElement>();const points=ref<(GraphNode&{x:number,y:number})[]>([]);const paths=ref<{d:string,label:string,x:number,y:number,source:string,target:string}[]>([]);const width=ref(800);const height=ref(200);const zoom=ref(1);const pan=ref({x:0,y:0});let drag:{x:number,y:number,px:number,py:number}|undefined;let revision=0;const marker=`arrow-${crypto.randomUUID()}`;
watch(()=>[props.nodes,props.edges],async()=>{const rev=++revision;const elk=new ELK();try{const graph=await elk.layout({id:'root',layoutOptions:{'elk.algorithm':'layered','elk.direction':'RIGHT','elk.layered.spacing.nodeNodeBetweenLayers':'60','elk.spacing.nodeNode':'32'},children:props.nodes.map(n=>({id:n.id,width:216,height:80})),edges:props.edges.map((e,i)=>({id:`e${i}`,sources:[e.source],targets:[e.target]}))} as ElkNode);if(rev!==revision)return;width.value=(graph.width??800)+24;height.value=(graph.height??200)+24;points.value=(graph.children??[]).map(n=>({...props.nodes.find(x=>x.id===n.id)!,x:(n.x??0)+12,y:(n.y??0)+12}));paths.value=(graph.edges??[]).flatMap((edge,i)=>(edge.sections??[]).map(s=>{const p=[s.startPoint,...(s.bendPoints??[]),s.endPoint];return{source:props.edges[i].source,target:props.edges[i].target,d:p.map((v,i)=>`${i?'L':'M'} ${v.x+12} ${v.y+12}`).join(' '),label:props.edges[i]?.label??'',x:s.startPoint.x+22,y:s.startPoint.y+5}}));zoom.value=1;pan.value={x:0,y:0};}catch(e){lab.fail(e)}},{immediate:true,deep:true});
function begin(e:PointerEvent){if((e.target as Element).closest('[data-node]'))return;drag={x:e.clientX,y:e.clientY,px:pan.value.x,py:pan.value.y};svg.value?.setPointerCapture(e.pointerId)}function move(e:PointerEvent){if(drag){const bounds=svg.value!.getBoundingClientRect();pan.value={x:drag.px+(e.clientX-drag.x)*width.value/bounds.width,y:drag.py+(e.clientY-drag.y)*height.value/bounds.height};}}
function source(){if(!svg.value)return '';const clone=svg.value.cloneNode(true)as SVGSVGElement;clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width',String(width.value));clone.setAttribute('height',String(height.value));clone.querySelectorAll('.motion-packet').forEach(n=>n.remove());clone.querySelectorAll('[stroke-dasharray]').forEach(n=>n.removeAttribute('stroke-dasharray'));clone.querySelector('g')?.setAttribute('transform','translate(0 0) scale(1)');return new XMLSerializer().serializeToString(clone)}
async function exportGraph(format:'svg'|'png'){const content=source();const path=await save({defaultPath:`数据库过程图.${format}`,filters:[{name:format.toUpperCase(),extensions:[format]}]});if(!path)return;if(format==='svg'){await api('export',{path,content});return}const blob=new Blob([content],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(2,8192/width.value,8192/height.value);const canvas=document.createElement('canvas');canvas.width=width.value*scale;canvas.height=height.value*scale;const ctx=canvas.getContext('2d')!;ctx.fillStyle='#f8fafc';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const png=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('PNG 导出失败'))));await api('export',{path,bytes:Array.from(new Uint8Array(await png.arrayBuffer()))});}finally{URL.revokeObjectURL(url)}}
defineExpose({source});
</script>
<template><section class="graph-view"><div class="graph-tools"><span>逻辑关系图</span><button @click="zoom=Math.min(4,zoom*1.25)">＋</button><button @click="zoom=Math.max(.25,zoom/1.25)">−</button><button @click="zoom=1;pan={x:0,y:0}">适应窗口</button><button @click="exportGraph('svg').catch(lab.fail)">SVG ↗</button><button @click="exportGraph('png').catch(lab.fail)">PNG ↗</button></div><svg ref="svg" :viewBox="`0 0 ${width} ${height}`" role="img" aria-label="数据库逻辑关系图" @pointerdown="begin" @pointermove="move" @pointerup="drag=undefined" @wheel.prevent="zoom=Math.max(.25,Math.min(4,zoom*($event.deltaY<0?1.1:.9)))"><defs><marker :id="marker" markerWidth="9" markerHeight="7" refX="8" refY="3.5" orient="auto"><path d="M0,0 L9,3.5 L0,7 Z" fill="#8c9eb8" /></marker></defs><g :transform="`translate(${pan.x} ${pan.y}) scale(${zoom})`"><g v-for="(edge,i) in paths" :key="i" :visibility="visibleEdges&&!visibleEdges.includes(edge.source+':'+edge.target)?'hidden':'visible'" :class="{'edge-active':edge.target===selected||activeEdges?.includes(edge.source+':'+edge.target),'edge-danger':dangerEdges?.includes(edge.source+':'+edge.target)}"><path :d="edge.d" fill="none" :stroke="dangerEdges?.includes(edge.source+':'+edge.target)?'#dc445d':edge.target===selected?'#2563eb':'#8c9eb8'" :stroke-width="edge.target===selected?4:2" :marker-end="`url(#${marker})`"/><path v-if="(edge.target===selected||activeEdges?.includes(edge.source+':'+edge.target))&&!reduced" class="motion-packet" :d="edge.d" fill="none" stroke="#34d399" stroke-width="6" pathLength="100" stroke-dasharray="9 91" :stroke-dashoffset="-(progress??0)*100"/><text v-if="edge.label" :x="edge.x" :y="edge.y" fill="#64748b" font-size="11" font-family="Microsoft YaHei, sans-serif">{{edge.label.slice(0,24)}}</text></g><g v-for="node in points" :key="node.id" :transform="`translate(${node.x},${node.y})`" :data-node="node.id" :class="{'node-current':node.id===selected,'node-complete':completed?.includes(node.id)}" role="button" tabindex="0" @click="emit('select',node.id)" @keydown.enter="emit('select',node.id)"><rect width="216" height="80" rx="12" :fill="node.id===selected?'#dbeafe':completed?.includes(node.id)?'#ecfdf5':'#ffffff'" :stroke="node.id===selected?'#2563eb':'#cbd5e1'" :stroke-width="node.id===selected?2.5:1.5"/><rect x="0" y="20" width="4" height="40" rx="2" :fill="node.id===selected?'#2563eb':'#10b981'"/><text x="15" y="28" font-size="14" font-weight="600" fill="#172b4d" font-family="Segoe UI, Microsoft YaHei, sans-serif">{{Array.from(node.label).slice(0,21).join('')}}</text><text x="15" y="51" font-size="12" fill="#64748b" font-family="Segoe UI, Microsoft YaHei, sans-serif">{{Array.from(node.detail??node.label.slice(21)).slice(0,25).join('')}}</text><title>{{node.label}} {{node.detail}}</title></g></g></svg><div v-if="!nodes.length" class="empty">运行查询或选择数据库后显示关系图</div></section></template>
